package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.history.AsOf;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The sheet's periods. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/periods")
public class PeriodController {

    /** A period as the screen shows it: its name, its from and to dates (YYYY-MM-DD), whether it is
     *  closed or soft-closed and, once either, the due-total fixed then and each person's fixed then, by person id
     *  (two decimals); and its cap on each person's open claims in it (none: no cap); and each person's carried
     *  figure fixed then, by person id; and each person's opening balance for it, by person id; and whether it is locked. */
    public record PeriodView(long id, String name, String from, String to, boolean closed, boolean soft, String closedTotal,
            Map<Long, String> closedPersonTotals, Integer cap, Map<Long, String> closedPersonCarried,
            Map<Long, String> openings, boolean locked) {

        static PeriodView of(Period p) {
            Map<Long, String> people = new TreeMap<>();
            p.getClosedPersonTotals().forEach((id, total) -> people.put(id, total.toPlainString()));
            Map<Long, String> carried = new TreeMap<>();
            p.getClosedPersonCarried().forEach((id, c) -> carried.put(id, c.toPlainString()));
            Map<Long, String> openings = new TreeMap<>();
            p.getOpenings().forEach((id, o) -> openings.put(id, o.toPlainString()));
            return new PeriodView(p.getId(), p.getName(), p.getFromDate().toString(), p.getToDate().toString(),
                    p.isClosed(), p.isSoftClosed(), p.getClosedTotal() == null ? null : p.getClosedTotal().toPlainString(), people,
                    p.getCap(), carried, openings, p.isLocked());
        }
    }

    /** A period to add: its cap on each person's open claims in it is a whole number of 1 or more, or none. */
    public record PeriodRequest(@NotBlank @Size(max = 200) String name, @NotNull LocalDate from,
            @NotNull LocalDate to, @Min(1) Integer cap) {
    }

    /** The months to generate periods for: a blank from-date takes the sheet's today. */
    public record GenerateRequest(LocalDate from, @NotNull LocalDate to) {
    }

    /** The fiscal year to generate periods for, by the calendar year its first day falls in. */
    public record GenerateFiscalYearRequest(@NotNull @Min(1) @Max(9998) Integer year) {
    }

    /** The calendar year to generate the four quarters of. */
    public record GenerateQuartersRequest(@NotNull @Min(1) @Max(9999) Integer year) {
    }

    /** Opening balances to paste: lines of name,period,amount. */
    public record OpeningsRequest(@NotNull @Size(max = 100000) String text) {
    }

    /** How many lines of opening balances went through. */
    public record OpeningsView(int count) {
    }

    private final PeriodService service;
    private final OpeningService openings;
    private final AsOf asOf;

    public PeriodController(PeriodService service, OpeningService openings, AsOf asOf) {
        this.service = service;
        this.openings = openings;
        this.asOf = asOf;
    }

    /** The sheet's periods, by from-date.; as they stood at the end of a date when the screen views the
     *  sheet as of one. */
    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestHeader(value = AsOf.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return (asOf == null ? service.list(sheetId.trim()) : this.asOf.periods(sheetId.trim(), asOf)).stream()
                .map(PeriodView::of).toList();
    }

    /** Add a period; refused when its name is taken, its dates run backwards or it overlaps another. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PeriodRequest request) {
        return PeriodView.of(service.add(sheetId.trim(), user.trim(), request.name(), request.from(), request.to(),
                request.cap()));
    }

    /** Generate a period per calendar month from the from-date's month to the to-date's month, leaving out
     *  any month whose name is taken or that overlaps a period; refused when the to-date is before the
     *  from-date. The periods made. */
    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid GenerateRequest request) {
        return service.generate(sheetId.trim(), user.trim(), request.from(), request.to()).stream()
                .map(PeriodView::of).toList();
    }

    /** Generate the twelve monthly periods of a fiscal year as the generator above does. The periods made. */
    @PostMapping("/generate-fiscal-year")
    public List<PeriodView> generateFiscalYear(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid GenerateFiscalYearRequest request) {
        return service.generateFiscalYear(sheetId.trim(), user.trim(), request.year()).stream()
                .map(PeriodView::of).toList();
    }

    /** Generate the four calendar quarters of a year, named yyyy-Q1 to yyyy-Q4, leaving out any quarter whose
     *  name is taken or that overlaps a period. The periods made. */
    @PostMapping("/generate-quarters")
    public List<PeriodView> generateQuarters(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid GenerateQuartersRequest request) {
        return service.generateQuarters(sheetId.trim(), user.trim(), request.year()).stream()
                .map(PeriodView::of).toList();
    }

    /** Paste opening balances, each line adding its amount to a person's carried figure for a period; refused
     *  whole when any line is wrong. How many lines went through. */
    @PostMapping("/openings")
    public OpeningsView pasteOpenings(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid OpeningsRequest request) {
        return new OpeningsView(openings.paste(sheetId.trim(), user.trim(), request.text()));
    }

    /** Close a period (a soft-closed one too), fixing its due-total afresh; refused when it is already closed. */
    @PostMapping("/{periodId}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return PeriodView.of(service.close(sheetId.trim(), user.trim(), periodId));
    }

    /** Soft-close a period, fixing its figures while its claims can still change; refused when it is
     *  already closed or soft-closed. */
    @PostMapping("/{periodId}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return PeriodView.of(service.softClose(sheetId.trim(), user.trim(), periodId));
    }

    /** Reopen a closed or soft-closed period, making its due-total live again; by a steward only, and refused when it
     *  is open. */
    @PostMapping("/{periodId}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return PeriodView.of(service.reopen(sheetId.trim(), user.trim(), periodId));
    }

    /** Lock a period, so it cannot be reopened; by a steward only, and refused when it is already locked. */
    @PostMapping("/{periodId}/lock")
    public PeriodView lock(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return PeriodView.of(service.lock(sheetId.trim(), user.trim(), periodId, true));
    }

    /** Unlock a period; by a steward only, and refused when it is not locked. */
    @PostMapping("/{periodId}/unlock")
    public PeriodView unlock(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return PeriodView.of(service.lock(sheetId.trim(), user.trim(), periodId, false));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.ActionNotAllowedException;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's periods: each uniquely named on the sheet, none overlapping another. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final Rollup rollup;
    private final RoleService roles;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, Rollup rollup, RoleService roles,
            Audit audit) {
        this.periods = periods;
        this.sheets = sheets;
        this.rollup = rollup;
        this.roles = roles;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        String n = name.trim();
        if (from.isAfter(to)) {
            throw new PeriodRefusedException("The from-date must be on or before the to-date.");
        }
        if (cap != null && cap < 1) {
            throw new PeriodRefusedException("The cap must be a whole number of 1 or more.");
        }
        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(n))) {
            throw new PeriodRefusedException("That period name is already in use.");
        }
        existing.stream().filter(p -> p.overlaps(from, to)).findFirst().ifPresent(p -> {
            throw new PeriodRefusedException("The period overlaps " + p.getName() + ".");
        });
        Period period;
        try {
            period = periods.saveAndFlush(new Period(sheetId, n, from, to, cap));
        } catch (DataIntegrityViolationException e) {
            throw new PeriodRefusedException("That period name is already in use.");
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
                + " period=" + n + " from=" + from + " to=" + to + (cap != null ? " cap=" + cap : ""));
        return period;
    }

    /** Generate one period per calendar month from the from-date's month to the to-date's month, each from
     *  the first to the last day of its month and named yyyy-mm; a month whose name is taken or whose days
     *  overlap a period on the sheet is left out. A blank from-date takes the sheet's today. Refused when
     *  the to-date is before the from-date. The periods made, in order. */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
        Sheet sheet = sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        LocalDate start = from == null ? sheet.getToday() : from;
        if (to.isBefore(start)) {
            throw new PeriodRefusedException("The to-date must be on or after the from-date.");
        }
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth m = YearMonth.from(start); !m.isAfter(YearMonth.from(to)); m = m.plusMonths(1)) {
            makeUnlessTaken(sheetId, user, m.toString(), m.atDay(1), m.atEndOfMonth(), existing, made);
        }
        return made;
    }

    /** Generate the four calendar quarters of a year, named yyyy-Q1 to yyyy-Q4, each as the period form
     *  would add it; a quarter whose name is taken or whose days overlap a period on the sheet is left out.
     *  The periods made, in order. */
    @Transactional
    public List<Period> generateQuarters(String sheetId, String user, int year) {
        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (int q = 1; q <= 4; q++) {
            YearMonth firstMonth = YearMonth.of(year, q * 3 - 2);
            makeUnlessTaken(sheetId, user, String.format("%04d-Q%d", year, q), firstMonth.atDay(1),
                    firstMonth.plusMonths(2).atEndOfMonth(), existing, made);
        }
        return made;
    }

    /** Make a period from first to last unless its name is taken or its days overlap one of the existing
     *  periods, adding it to both lists. */
    private void makeUnlessTaken(String sheetId, String user, String name, LocalDate first, LocalDate last,
            List<Period> existing, List<Period> made) {
        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(name) || p.overlaps(first, last))) {
            return;
        }
        Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
        existing.add(period);
        made.add(period);
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
                + " period=" + name + " from=" + first + " to=" + last);
    }

    /** Generate the twelve monthly periods of a fiscal year, exactly as {@link #generate} does from the
     *  first month of the year to its last: the fiscal year starts on the first day of the sheet's fiscal
     *  start month in the year it is named by. The periods made, in order. */
    @Transactional
    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
        // Locking the sheet first reads the fiscal start month as it stands while the periods are made.
        Sheet sheet = sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        LocalDate first = LocalDate.of(year, sheet.getFiscalStartMonth(), 1);
        return generate(sheetId, user, first, first.plusYears(1).minusDays(1));
    }

    /** Close a period, fixing each person's due-total and carried figure for it and its own as it is now; refused when the user's role may not
     *  close it, or it is already closed. A soft-closed period can be closed, fixing its figures afresh. */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        // Locking the sheet makes the close and any claim change on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        roles.require(sheetId, user, "close");
        if (period.isClosed()) {
            throw new PeriodRefusedException("The period is already closed.");
        }
        return closeNow(sheetId, user, period, false);
    }

    /** Soft-close a period, fixing each person's due-total and carried figure for it and its own as it is now while its claims
     *  can still change; refused when the user's role may not close it, or it is already closed or
     *  soft-closed. */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        // Locking the sheet makes the soft close and any claim change on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        roles.require(sheetId, user, "close");
        if (period.isClosed() || period.isSoftClosed()) {
            throw new PeriodRefusedException("The period is already closed.");
        }
        period.softClose(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedByPerson(sheetId, period, periods.findBySheetIdOrderByFromDateAsc(sheetId)));
        periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user
                + " period=" + period.getName() + " total=" + period.getClosedTotal().toPlainString());
        return period;
    }

    /** Close, in order of their to-dates, every open period whose to-date plus the grace days is before the
     *  sheet's (new) today, each as a close by hand would (a soft-closed period keeps its fixed figures); none
     *  when the grace days are off. The caller holds the sheet's lock. */
    @Transactional
    public void closeOverdue(String sheetId, String user, LocalDate today, Integer graceDays) {
        if (graceDays == null) {
            return;
        }
        periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> closeNow(sheetId, user, p, true));
    }

    private Period closeNow(String sheetId, String user, Period period, boolean auto) {
        period.close(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedByPerson(sheetId, period, periods.findBySheetIdOrderByFromDateAsc(sheetId)));
        periods.saveAndFlush(period);
        BigDecimal total = period.getClosedTotal();
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user
                + " period=" + period.getName() + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
        return period;
    }

    /** Reopen a closed or soft-closed period, making its due-total and each person's carried figure live again; by a role the sheet allows (a steward
     *  by the standing rule), and refused when it is open. */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        // Locking the sheet makes the reopen and any claim change on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        roles.require(sheetId, user, "reopen");
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new PeriodRefusedException("The period is not closed.");
        }
        if (period.isLocked()) {
            throw new PeriodRefusedException("The period is locked.");
        }
        period.reopen();
        periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + period.getName());
        return period;
    }

    /** Lock or unlock a period; by a steward only, and refused when it is already locked (or unlocked). */
    @Transactional
    public Period lock(String sheetId, String user, long periodId, boolean locked) {
        // Locking the sheet makes the lock and any reopen on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!roles.isSteward(sheetId, user)) {
            throw new ActionNotAllowedException(locked ? "lock a period" : "unlock a period");
        }
        if (period.isLocked() == locked) {
            throw new PeriodRefusedException(locked ? "The period is already locked." : "The period is not locked.");
        }
        period.setLocked(locked);
        periods.saveAndFlush(period);
        audit.recordOnCommit((locked ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
                + " period=" + period.getName());
        return period;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The opening balances paste: lines of name,period,amount, each adding its amount to the opening balance of
 * the person on the sheet with the name or an alias (ignoring case) for the period on the sheet with the name
 * (ignoring case), and so to their carried figure for it. The amount has up to two decimals and is 0.00 or more.
 * Blank lines are skipped. Every line is checked first; a refused line refuses the paste, adding nothing and
 * writing nothing.
 */
@Service
public class OpeningService {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}(\\.\\d{1,2})?");

    private final PeriodRepository periods;
    private final PersonRepository people;
    private final SheetRepository sheets;
    private final Audit audit;

    public OpeningService(PeriodRepository periods, PersonRepository people, SheetRepository sheets, Audit audit) {
        this.periods = periods;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    private record Line(Person person, Period period, BigDecimal amount) {
    }

    /** Paste opening balances: how many lines went through. */
    @Transactional
    public int paste(String sheetId, String user, String text) {
        // Locking the sheet makes two users' pastes, and a close, go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        List<Period> sheetPeriods = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        List<Line> lines = new ArrayList<>();
        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                lines.add(parse(sheetId, sheetPeriods, i + 1, raw[i]));
            }
        }
        if (lines.isEmpty()) {
            throw new PeriodRefusedException("Paste at least one line of name,period,amount.");
        }
        for (Line line : lines) {
            line.period().addOpening(line.person().getId(), line.amount());
            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
                    + " period=" + line.period().getName() + " amount=" + line.amount().toPlainString());
        }
        lines.stream().map(Line::period).distinct().forEach(periods::saveAndFlush);
        return lines.size();
    }

    private Line parse(String sheetId, List<Period> sheetPeriods, int number, String raw) {
        String[] f = raw.split(",", -1);
        if (f.length != 3) {
            throw refused(number, "enter name,period,amount.");
        }
        String name = f[0].trim();
        if (name.isEmpty() || name.length() > 200) {
            throw refused(number, "enter a name.");
        }
        Person person = people.findByNameOrAlias(sheetId, name)
                .orElseThrow(() -> refused(number, "no one on the sheet is named " + name + "."));
        String periodName = f[1].trim();
        Period period = sheetPeriods.stream().filter(p -> p.getName().equalsIgnoreCase(periodName)).findFirst()
                .orElseThrow(() -> refused(number, "no period on the sheet is named " + periodName + "."));
        String amount = f[2].trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw refused(number, "enter an amount of 0.00 or more with up to two decimals.");
        }
        return new Line(person, period, new BigDecimal(amount).setScale(2));
    }

    private static PeriodRefusedException refused(int number, String why) {
        return new PeriodRefusedException("Line " + number + ": " + why);
    }
}

