160	    /** The figures of every descendant of a sheet, as {@link #descendants(String)}, each sheet as it stood at the
161	     *  end of a date, that date its today; as they are now with no date. */
162	    public Consolidated descendants(String sheetId, LocalDate date) {
163	        Set<String> seen = new LinkedHashSet<>(List.of(sheetId));
164	        List<String> todo = new ArrayList<>(List.of(sheetId));
165	        int peopleCount = 0;
166	        BigDecimal due = ZERO;
167	        BigDecimal overdue = ZERO;
168	        Map<String, BigDecimal> gradeDues = new LinkedHashMap<>();
169	        Map<ClaimStatus, Integer> statusCounts = new LinkedHashMap<>();
170	        List<Member> members = new ArrayList<>();
171	        while (!todo.isEmpty()) {
172	            for (Sheet child : sheets.findByParentOrderByIdAsc(todo.remove(0))) {
173	                if (!seen.add(child.getId())) {
174	                    continue;
175	                }
176	                todo.add(child.getId());
177	                Snapshot snapshot = date == null ? take(child.getId()) : take(child.getId(), date);
178	                peopleCount += snapshot.people().size();
179	                due = due.add(snapshot.dueTotal());
180	                overdue = overdue.add(snapshot.overdueTotal());
181	                Breakdown breakdown = breakdown(child.getId(), date, snapshot);
182	                breakdown.gradeDueTotals().forEach((g, d) -> gradeDues.merge(g, d, BigDecimal::add));
183	                breakdown.statusCounts().forEach((st, n) -> statusCounts.merge(st, n, Integer::sum));
184	                members.addAll(members(child.getId(), date, snapshot));
185	            }
186	        }
187	        return new Consolidated(peopleCount, due, overdue, gradeDues, statusCounts, members);
188	    }
