358	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
359	                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal())
360	                        + " overdue-total=" + now.overdueTotal().toPlainString());
361	            }
362	        });
363	        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
364	                || before.dueTotal().compareTo(after.dueTotal()) != 0
365	                || before.overdueTotal().compareTo(after.overdueTotal()) != 0) {
366	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
367	                    + " due-total=" + after.dueTotal().toPlainString()
368	                    + " overdue-total=" + after.overdueTotal().toPlainString());
369	        }
370	        recordAlerts(sheetId, prefix, before, after);
371	    }
372	
373	    /** Record, once the change commits, an ALERT line for each person whose due-total went from at or below the
374	     *  sheet's alert threshold (or none, or new to the sheet) to above it, in the list order; none when the
375	     *  threshold is off. */
376	    private void recordAlerts(String sheetId, String prefix, Snapshot before, Snapshot after) {
377	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
378	        if (threshold == null) {
379	            return;
380	        }
381	        after.people().forEach((id, now) -> {
382	            Figures was = before == null ? null : before.people().get(id);
383	            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
384	                audit.recordOnCommit("ALERT" + prefix + " name=" + now.name() + " due-total=" + show(now.dueTotal()));
385	            }
386	        });
387	    }
388	
389	    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
390	        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
391	    }
392	
393	    /** Whether a claim counts toward claimed: its status counts, it is not left out by its person's
394	     *  retirement (a hold leaves it in), and it is not deferred past the sheet's today. */
395	    private static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
396	        return claim.getStatus().counts() && !retiredOut(claim, person, today) && !claim.deferredOn(today);
397	    }
398	
399	    /** Whether a claim counted by the status it had at the end of a day, as its status log records it:
400	     *  its latest line dated on or before it; not when it was added after it. A claim with no log counts
401	     *  by its status now. */
402	    private static boolean countsAt(Claim claim, LocalDate day) {
403	        ClaimStatus status = statusAt(claim, day);
404	        return status != null && status.counts();
405	    }
406	
407	    /** The status a claim had at the end of a day, as its status log records it: its latest line dated on or
408	     *  before it; none when it was added after it. A claim with no log has its status now. */
409	    private static ClaimStatus statusAt(Claim claim, LocalDate day) {
410	        List<StatusChange> log = claim.getStatusLog();
411	        if (log.isEmpty()) {
412	            return claim.getStatus();
413	        }
414	        ClaimStatus status = null;
415	        for (StatusChange change : log) {
416	            if (!change.getOn().isAfter(day)) {
417	                status = change.getStatus();
418	            }
419	        }
420	        return status;
421	    }
422	
423	    /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus the grace days of its
424	     *  person's grade in force on its date before the sheet's today. */
425	    private static boolean overdue(Optional<Sheet> sheet, Claim claim, Person person, LocalDate today) {
426	        return claim.getStatus().isOpen() && !claim.deferredOn(today) && today != null && claim.getDueBy() != null
427	                && lateFrom(sheet, claim, person).isBefore(today);
428	    }
429	
430	    /** The date a claim's lateness runs from: its due-by plus the grace days in force on its date of its
431	     *  person's grade in force then. */
432	    public static LocalDate lateFrom(Optional<Sheet> sheet, Claim claim, Person person) {
433	        String grade = person == null ? null : person.gradeOn(claim.getDate());
434	        return sheet.map(s -> s.lateFrom(claim.getDueBy(), grade, claim.getDate())).orElse(claim.getDueBy());
435	    }
436	
437	    /** Whether a retirement leaves a claim out of claimed: it is OPEN or PENDING, bound by no statement, and
438	     *  its person's retirement date is reached on the sheet's today. */
439	    private static boolean retiredOut(Claim claim, Person person, LocalDate today) {
440	        return person != null && claim.getStatus().isOpen() && !claim.isBound() && person.retiredBy(today);
441	    }
442	
443	    /** Whether a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound by no
444	     *  statement, and its person's retirement date is reached on the sheet's today. A hold no longer does:
445	     *  it only takes a person's cut out of the pools. */
446	    public static boolean heldOut(Claim claim, Person person, LocalDate today) {
447	        return retiredOut(claim, person, today);
448	    }
449	
450	    /** A claim's amount at a rate, divided by 100, rounded to cents as the claim's rounding date rounds on
451	     *  the sheet (half to even with no sheet). */
452	    public static BigDecimal rated(Optional<Sheet> sheet, Claim claim, List<Claim> sheetClaims, Rate rate) {
453	        LocalDate on = roundingDate(claim, sheetClaims);
454	        return claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
455	                .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN));
456	    }
457	
458	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it
459	     *  corrects (the claim of the same person with that number), its own when that is not found. */
460	    public static LocalDate roundingDate(Claim claim, List<Claim> sheetClaims) {
461	        if (!claim.isCorrection()) {
462	            return claim.getDate();
463	        }
464	        return sheetClaims.stream()
465	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
466	                .findFirst().map(Claim::getDate).orElse(claim.getDate());
467	    }
468	
469	    /** A claim's due from its figure: at least the sheet's floor in force on its date, then its late charge,
470	     *  worked out on that floored figure, on top while it is OPEN or PENDING (only those go overdue). A settled claim's due is frozen (it
471	     *  already holds the charge and floor fixed when it was settled), as is a bound one's (its statement bound
472	     *  the due as shown then, charge and floor included); a correction has neither late charge nor floor, and a
473	     *  waived claim no late charge. */
474	    public static BigDecimal charged(Optional<Sheet> sheet, Claim claim, Person person, BigDecimal figure) {
475	        if (claim.getSettledDue() != null || claim.isBound() || claim.isCorrection()) {
476	            return figure;
477	        }
478	        return sheet.map(s -> {
479	                    BigDecimal floored = s.floored(figure, claim.getDate());
480	                    return claim.getStatus().isOpen() && !claim.isWaived()
481	                            ? floored.add(s.lateCharge(floored, lateFrom(sheet, claim, person), claim.getDate())) : floored;
482	                })
483	                .orElse(figure);
484	    }
485	
486	    /** A person's due-total at most the sheet's cap. */
487	    private static BigDecimal capped(Optional<Sheet> sheet, BigDecimal dueTotal) {
488	        return sheet.map(s -> s.capped(dueTotal)).orElse(dueTotal);
489	    }
490	
491	    private static boolean sameDue(BigDecimal a, BigDecimal b) {
492	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
493	    }
494	
495	    private static String show(BigDecimal due) {
496	        return due == null ? "n/a" : due.toPlainString();
497	    }
498	
499	    /** The grade's rate in force on a date for a claim: as {@link #inForce(List, String, LocalDate)}, each rate
500	     *  as it applies to the claim (a forward-only rate not to a claim already on the sheet when it was saved,
501	     *  which keeps what applied to it). */
502	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date, Claim claim) {
503	        List<Rate> forClaim = new ArrayList<>();
504	        sheetRates.forEach(r -> r.forClaim(claim.getId()).ifPresent(forClaim::add));
505	        return inForce(forClaim, grade, date);
506	    }
507	
508	    /** The grade's rate in force on a date: the latest from-date on or before it, none first; none
509	     *  when the date is after that rate's to-date. The rates may be a sheet's followed by its ancestors',
510	     *  nearest first: the first sheet, in that order, with a rate of the grade in force then gives it. */
511	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
512	        Set<String> sheetIds = new LinkedHashSet<>();
513	        sheetRates.forEach(r -> sheetIds.add(r.getSheetId()));
514	        for (String sheetId : sheetIds) {
515	            Optional<Rate> found = inForceOn(sheetRates, sheetId, grade, date);
516	            if (found.isPresent()) {
517	                return found;
518	            }
519	        }
520	        return Optional.empty();
521	    }
522	
523	    private static Optional<Rate> inForceOn(List<Rate> sheetRates, String sheetId, String grade, LocalDate date) {
524	        return sheetRates.stream()
525	                .filter(r -> r.getSheetId().equals(sheetId) && r.getGrade().equals(grade))
526	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
527	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
528	                .filter(r -> r.coversThrough(date));
529	    }
530	}
